1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Collection;
4	
5	/**
6	 * The owner's region-and-hash identity. The customerCode is formatted {@code <REGION>-<HASH8>} where
7	 * REGION is the region derived from the owner's postcode (see {@link Locality}) and HASH8 is the first
8	 * eight upper-case hex characters of SHA-256 over the normalized telephone concatenated with the last
9	 * name (see {@link Sha256}). The identity carries no per-owner sequence, so it does not depend on other
10	 * owners; the same telephone and last name always yield the same hash. Every value derived from the
11	 * customerCode — the membership number and its check digit, the create audit record and the locality —
12	 * therefore shares this single identity. Pure functions, so exposed as plain helpers.
13	 */
14	public final class CustomerCode {
15	
16	    /** Number of hex characters in the hash portion of the code. */
17	    private static final int HASH_LENGTH = 8;
18	
19	    private CustomerCode() {
20	    }
21	
22	    /**
23	     * Builds the customerCode {@code <region>-<HASH8>}. The hash is taken over the normalized telephone
24	     * followed by the last name; a {@code null} part contributes an empty string.
25	     */
26	    public static String of(String region, String normalizedTelephone, String lastName) {
27	        return region + "-" + Sha256.prefix(orEmpty(normalizedTelephone) + orEmpty(lastName), HASH_LENGTH);
28	    }
29	
30	    /**
31	     * De-duplicates {@code candidate} against the {@code existing} customerCodes. Returns the candidate
32	     * unchanged when it does not collide; otherwise appends {@code -<n>} with the smallest {@code n} of 2
33	     * or more that yields a value absent from {@code existing}.
34	     */
35	    public static String dedupe(String candidate, Collection<String> existing) {
36	        if (!existing.contains(candidate)) {
37	            return candidate;
38	        }
39	        for (int n = 2; ; n++) {
40	            String deduped = candidate + "-" + n;
41	            if (!existing.contains(deduped)) {
42	                return deduped;
43	            }
44	        }
45	    }
46	
47	    /** The region portion (before the first '-') of a customerCode, or {@code null} when absent. */
48	    public static String regionOf(String customerCode) {
49	        if (customerCode == null) {
50	            return null;
51	        }
52	        int dash = customerCode.indexOf('-');
53	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
54	    }
55	
56	    private static String orEmpty(String value) {
57	        return value == null ? "" : value;
58	    }
59	}
60

1	package org.springframework.samples.petclinic.util;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Scores an owner's membership points. The score starts at 0 and gains {@link #EMAIL_POINTS} when an
7	 * email address is present, {@link #UNIQUE_NAME_POINTS} when the owner has a unique name
8	 * (namesakeCount is zero), {@link #HOUSEHOLD_POINTS} for a household of {@link #HOUSEHOLD_MIN} or more
9	 * members, and {@link #TENURE_POINTS} when the owner's {@link Tenure tenure} exceeds
10	 * {@link #TENURE_DAYS} days. Because a newly created owner has zero tenure, a new owner never earns
11	 * the tenure points. The points band into a {@link MembershipLevel membership level}.
12	 */
13	public final class MembershipPoints {
14	
15	    /** Points awarded when an email address is present. */
16	    public static final int EMAIL_POINTS = 2;
17	
18	    /** Points awarded when the owner has a unique name (namesakeCount is zero). */
19	    public static final int UNIQUE_NAME_POINTS = 1;
20	
21	    /** Points awarded for a household of {@link #HOUSEHOLD_MIN} or more members. */
22	    public static final int HOUSEHOLD_POINTS = 2;
23	
24	    /** Points awarded when tenure exceeds {@link #TENURE_DAYS} days. */
25	    public static final int TENURE_POINTS = 3;
26	
27	    /** Household size at or above which the household points are awarded. */
28	    public static final int HOUSEHOLD_MIN = 3;
29	
30	    /** Tenure in days beyond which the tenure points are awarded. */
31	    public static final int TENURE_DAYS = 365;
32	
33	    private MembershipPoints() {
34	    }
35	
36	    /** The membership points for {@code owner}, or {@code null} when the owner is {@code null}. */
37	    public static Integer of(Owner owner) {
38	        if (owner == null) {
39	            return null;
40	        }
41	        int points = 0;
42	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
43	            points += EMAIL_POINTS;
44	        }
45	        Integer namesakeCount = owner.getNamesakeCount();
46	        if (namesakeCount != null && namesakeCount == 0) {
47	            points += UNIQUE_NAME_POINTS;
48	        }
49	        Integer householdSize = owner.getHouseholdSize();
50	        if (householdSize != null && householdSize >= HOUSEHOLD_MIN) {
51	            points += HOUSEHOLD_POINTS;
52	        }
53	        if (Tenure.days(owner) > TENURE_DAYS) {
54	            points += TENURE_POINTS;
55	        }
56	        return points;
57	    }
58	}
